import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = "D:/Packages/PI-Desktop/worktrees/owner-local-control";
const scratch = process.env.PI_SCRATCH_DIR;
const output = join(scratch, "handoff-plugin-callbacks-candidate.json");
assert.equal(existsSync(output), false, "Candidate evidence already exists");
const git = (...args) => execFileSync("git", args, { cwd: root, encoding: "utf8" }).trim();
const hash = bytes => createHash("sha256").update(bytes).digest("hex");
const candidate = git("rev-parse", "HEAD"), base = git("rev-parse", "origin/main");
assert.equal(candidate, "27f394700e8f963640319125a71eafb924c82c28");
assert.equal(git("status", "--porcelain"), "");
git("merge-base", "--is-ancestor", "origin/main", "HEAD");
const focused = [...new Set([
  ...git("diff-tree", "--no-commit-id", "--name-only", "-r", "HEAD").split("\n").filter(file => /\.(?:ts|mjs)$/.test(file)),
  "apps/desktop/electron/main/plugin-lifecycle.ts", "apps/desktop/electron/main/plugin-loading.ts",
  "apps/desktop/electron/main/plugin-tool-invocations.ts", "apps/desktop/electron/main/plugin-host-process.mjs",
  "apps/desktop/electron/main/mcp-call-registry.ts", "apps/desktop/electron/main/runtime/handoff-admission.ts",
  "packages/agent-host/src/maintenance-admission.ts", "packages/host-runtime/plugin-host-process.mjs",
  "packages/host-runtime/src/mcp/http-transport.ts", "packages/host-runtime/src/mcp/transport.ts",
  "apps/desktop/test/helpers/current-source-import-hooks.mjs", "apps/desktop/test/helpers/ts-import-hooks.mjs",
  "apps/desktop/test/helpers/owner-runtime-import-hooks.mjs",
])].sort();
const inputs = () => focused.map(path => ({ path, sha256: hash(readFileSync(join(root, path))) }));
const before = inputs(), runs = [], startedAt = new Date().toISOString();
const env = { ...process.env, TEMP: scratch, TMP: scratch,
  PI_COMMAND_CENTER_DEPENDENCIES: "C:/Users/Administrator/.pi-desktop/scratch/a6fa9016-c24e-432f-8859-b0744dea889d/p0-dependencies" };
for (const [name, path, expected] of [
  ["regressions", "apps/desktop/test/handoff-plugin-callbacks.test.mjs", 22],
  ["process", "apps/desktop/test/plugin-lifecycle-user-path.e2e.mjs", 3],
]) {
  const args = ["--test", "--test-timeout=25000", path];
  const result = spawnSync(process.execPath, args, { cwd: root, env, encoding: "utf8", timeout: 55000, maxBuffer: 8 * 1024 * 1024 });
  const text = (result.stdout ?? "") + (result.stderr ?? "");
  const log = `handoff-plugin-callbacks-candidate-${name}.log`;
  writeFileSync(join(scratch, log), text);
  const pass = Number(text.match(/ℹ pass (\d+)/)?.[1]);
  const fail = Number(text.match(/ℹ fail (\d+)/)?.[1]);
  const cancelled = Number(text.match(/ℹ cancelled (\d+)/)?.[1]);
  const skipped = Number(text.match(/ℹ skipped (\d+)/)?.[1]);
  runs.push({ name, args, exitCode: result.status, signal: result.signal, error: result.error?.message,
    pass, fail, cancelled, skipped, expected, log, sha256: hash(text), bytes: Buffer.byteLength(text),
    diagnostics: [...text.matchAll(/^ℹ (\{.*\})$/gm)].map(match => JSON.parse(match[1])) });
  console.log(JSON.stringify({ name, exitCode: result.status, pass, fail, cancelled, skipped }));
}
const after = inputs(), cleanAfter = git("status", "--porcelain") === "";
const originalProcesses = runs.flatMap(run => run.diagnostics);
const passed = runs.every(run => run.exitCode === 0 && run.pass === run.expected && run.fail === 0 && run.cancelled === 0 && run.skipped === 0)
  && cleanAfter && JSON.stringify(before) === JSON.stringify(after) && originalProcesses.length === 3
  && originalProcesses.every(record => record.originalExitsObserved && record.activity.operations === 0 && record.activity.plugins === 0 && record.activity.schedules === 0 && record.activity.uncontainedResources > 0);
const report = { status: passed ? "PASS_WITH_UNQUALIFIED_NATIVE_RESOURCES" : "FAIL", candidate, base, startedAt,
  endedAt: new Date().toISOString(), platform: process.platform, node: process.version, nodeSha256: hash(readFileSync(process.execPath)),
  cleanBefore: true, cleanAfter, inputsUnchanged: JSON.stringify(before) === JSON.stringify(after),
  inputScope: "Focused changed files and direct lifecycle/transport/test-loader inputs; not a complete bundle or dependency manifest",
  inputs: before, runs, originalChildren: originalProcesses.reduce((total, record) => total + record.originalProcesses, 0),
  qualifiedNativeFamilyClosure: false, fullDesktopTransfer: false, hardwareQualification: false };
writeFileSync(output, JSON.stringify(report, null, 2) + "\n");
assert.equal(passed, true, "Candidate failed; inspect retained evidence");
console.log(JSON.stringify({ output, status: report.status, candidate, cleanAfter, inputCount: before.length, originalChildren: report.originalChildren }));
